// Supports both integer-seconds and HTTP-date forms (RFC 7231). Returns 0 when
// the header is absent or unparseable, so the caller falls back to backoff.
func parseRetryAfter(resp *http.Response) int {
	headerVal := resp.Header.Get("Retry-After")
	if headerVal == "" {
		return 0
	}
	if secs, err := parse.Int(headerVal); err == nil {
		return secs * 1000
	}
	if t, err := http.ParseTime(headerVal); err == nil {
		return int(time.Until(t).Milliseconds())
	}
	return 0
}

